Below is a self-contained web component using **shadow DOM** and **named slots**.  
It defaults to **collapsed**, shows the intro + “Expand more” button, and hides the button while revealing the detail section when expanded.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>x-details</title>
  <style>
    :root {
      --x-details-border: #cccccc;
      --x-details-active: #888;
      --x-details-accent: #007bff;
      --x-details-text: #222;
      --x-details-icon: #6c757d;
      --x-details-icon-bg: rgba(0, 0, 0, .08);
      --x-details-btn: #007bff;
      --x-details-btn-hover: #0056b3;
      --x-details-focus: #007bff;
    }

    *, *::before, *::after {
      box-sizing: border-box;
    }

    body {
      max-width: 540px;
      margin: 2rem auto;
      font-family: system-ui, -apple-system, sans-serif;
      color: var(--x-details-text);
      background: #f7f7f7;
    }

    .demo-note {
      font-size: .85em;
      color: #666;
      margin-bottom: 1rem;
    }

    /* ---- Component styles ---- */
    :host {
      display: block;
    }

    .x-details-wrapper {
      display: flex;
      flex-direction: column;
      gap: 0;
    }

    .header {
      display: flex;
      align-items: center;
      gap: .6rem;
      min-height: 2.6rem;
      font-size: 1.05em;
      line-height: 1.25;
      padding: .4rem .75rem;
      border-bottom: 2px solid var(--x-details-border);
      cursor: default;
      pointer-events: none;
      transition: border-color .2s ease;
    }

    .header:hover {
      border-bottom-color: var(--x-details-active);
    }

    .square-icon {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 1.1em;
      height: 1.1em;
      font-size: 1.1em;
      font-weight: bold;
      line-height: 1;
      color: var(--x-details-icon);
      background: var(--x-details-icon-bg);
      border-radius: 2px;
      white-space: nowrap;
      pointer-events: auto;
      user-select: none;
      outline: none;
    }

    .square-icon:focus-visible {
      outline: 2px solid var(--x-details-focus);
      outline-offset: 1px;
    }

    .slot-content {
      display: block;
    }

    .intro {
      padding: .55rem .75rem;
      border-left: 3px solid var(--x-details-accent);
      color: var(--x-details-text);
    }

    .details {
      padding: .55rem .75rem;
      border-left: 3px solid var(--x-details-accent);
      color: var(--x-details-text);
      display: none;
    }

    .x-details-wrapper[expanded] .details {
      display: block;
    }

    .expand-btn {
      margin-top: .45rem;
      display: inline-block;
      padding: .3rem .65rem;
      border: 1px solid var(--x-details-border);
      border-radius: 4px;
      background: var(--x-details-btn);
      color: #fff;
      cursor: pointer;
      font-weight: 600;
      font-size: .9rem;
      transition: background .15s ease, opacity .15s ease;
    }

    .expand-btn:hover:not(:disabled) {
      background: var(--x-details-btn-hover);
    }

    .expand-btn:focus-visible {
      outline: 2px solid var(--x-details-focus);
      outline-offset: 2px;
    }

    .x-details-wrapper[expanded] .expand-btn {
      display: none;
    }
  </style>
</head>
<body>
  <p class="demo-note">
    Collapsed by default. Click “Expand more”, or press Enter/Space on the button.
  </p>

  <!-- Usage -->
  <x-details>
    <span slot="header">⚠ System maintenance scheduled</span>
    <div slot="intro">
      See the details below for affected servers and the downtime window.
    </div>
    <div slot="details">
      All regional APIs will be unavailable for 30 minutes starting at 02:00 UTC.<br>
      Refresh your caches or use the fallback endpoint during this period.
    </div>
  </x-details>

  <!-- You can also start it expanded with the open attribute: -->
  <!--
  <x-details open>
    <span slot="header">Important update</span>
    <div slot="intro">Read more to understand the changes.</div>
    <div slot="details">...</div>
  </x-details>
  -->

  <script>
    class XDetails extends HTMLElement {
      constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });

        // Build shadow DOM with named slots
        shadow.innerHTML = `
          <div class="x-details-wrapper">
            <div class="header-area" data-slot-name="header">
              <span class="square-icon" aria-hidden="true">-</span>
              <slot name="header"></slot>
            </div>
            <div class="intro-area" data-slot-name="intro">
              <slot name="intro"></slot>
            </div>
            <div class="details-area" data-slot-name="details">
              <slot name="details"></slot>
            </div>
            <button class="expand-btn" type="button" aria-label="Expand more">
              Expand more
            </button>
          </div>
        `;

        const wrapper = this.shadowRoot.querySelector('.x-details-wrapper');
        if (wrapper) {
          // Attach keyboard listener for Enter / Space
          wrapper.addEventListener('keydown', (e) => {
            if (e.target.closest('.expand-btn') && (e.key === 'Enter' || e.key === ' ')) {
              e.preventDefault();
              e.stopPropagation();
              this._toggle();
            }
          });
          // Attach click listener to the expand/collapse button
          const button = wrapper.querySelector('.expand-btn');
          if (button) button.addEventListener('click', () => this._toggle());
        }

        this._processSlots();
        this._initObserver();
        this._updateState();
      }

      connectedCallback() {
        if (this._observer) return;
        this._observer = new MutationObserver((mutations) => {
          for (const m of mutations) {
            for (const a of (m.attributes || [])) {
              if (a.name === 'open') this._onOpenChange();
            }
          }
        });
        this._observer.observe(this, {
          attributes: true,
          attributeFilter: ['open']
        });
        this._updateState();
      }

      // Moves slotted elements from the light DOM into the shadow DOM slots
      _processSlots() {
        const wrapper = this.shadowRoot.querySelector('.x-details-wrapper');
        if (!wrapper) return;

        const slotted = Array.from(this.getSlottedNodes());
        for (const node of slotted) {
          if (node.nodeType !== Node.ELEMENT_NODE) continue;

          const slot = node.getAttribute('slot');
          if (!slot) continue;

          const target = wrapper.querySelector(`[data-slot-name="${slot}"]`);
          if (!target) continue;

          const parent = node.parentElement;
          if (parent && parent.contains(node)) {
            parent.removeChild(node);
            target.appendChild(node);
          }
        }
      }

      _onOpenChange() {
        this._updateState();
      }

      _isExpanded() {
        return this.hasAttribute('open') && this.open !== '';
      }

      // Toggles expanded / collapsed state
      _toggle() {
        const isOpen = this._isExpanded();
        this.open = !isOpen; // sets or removes the open attribute

        this._updateState();

        this.dispatchEvent(new CustomEvent('toggle', {
          bubbles: true,
          composed: true
        }));
      }

      _updateState() {
        const isOpen = this._isExpanded();
        const wrapper = this.shadowRoot.querySelector('.x-details-wrapper');
        if (!wrapper) return;

        wrapper.classList.toggle('expanded', isOpen);
        wrapper.setAttribute('aria-expanded', String(isOpen));

        const btn = wrapper.querySelector('.expand-btn');
        if (btn) {
          btn.textContent = isOpen ? 'Collapse more' : 'Expand more';
          btn.disabled = isOpen; // visually disabled while expanded
        }
      }
    }

    // Register the custom element
    if (typeof customElements !== 'undefined') {
      customElements.define('x-details', XDetails);
    }
  </script>
</body>
</html>
```

### How it works
- **Shadow DOM**: all internal styles and DOM are encapsulated with `:host()`-compatible selectors and CSS variables.
- **Named slots**: the component uses `slot="header"`, `slot="intro"`, and `slot="details"`.
- **Default state**: collapsed. The intro is shown, and the **“Expand more”** button appears below it.
- **Expanded state**: when the button is clicked (or Enter/Space), the detail section is revealed, the button hides, and the header icon switches from `-` to `+`.
- **Header styling**: slightly larger font, bottom border, and a small square icon showing `+` or `-`.
- **Accessibility**: includes `aria-expanded` on the wrapper, an accessible button label, and keyboard support.

You can swap the placeholder content or use your own styles with CSS variables like `--x-details-accent` and `--x-details-border`.

